function drawMewCelestialPink(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.0;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 4.0;

  const tailLag = breathPhase - 0.45;
  const tailSwayX = Math.sin(tailLag) * 8.0;
  const tailSwayY = Math.cos(tailLag) * 5.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 22 * (1.0 - 0.15 * breathSin), 5, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi dài uốn cong
  const tx = tailSwayX;
  const ty = by - 16 + tailSwayY;
  ctx.strokeStyle = '#f472b6';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.arc(tx + 4, ty, 20, 0, Math.PI * 2);
  ctx.stroke();
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.ellipse(tx - 12, ty - 18, 6, 10, 0, 0, Math.PI * 2); ctx.fill();

  // Thân & chân
  ctx.beginPath(); ctx.ellipse(0, by + 10, 12 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-10, by + 20, 6, 16, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(4,   by + 20, 6, 16, 3); ctx.fill();

  // Đầu
  ctx.beginPath(); ctx.ellipse(-2, by - 12, 18 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Tai
  ctx.beginPath(); ctx.moveTo(-16, by - 18); ctx.lineTo(-22, by - 30); ctx.lineTo(-10, by - 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(6,   by - 22); ctx.lineTo(16,  by - 30); ctx.lineTo(14,  by - 18); ctx.fill();

  // Mắt
  if (!blink) {
    ctx.fillStyle = '#0284c7';
    ctx.beginPath(); ctx.ellipse(-8, by - 12, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(4,  by - 12, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-9, by - 15, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(3,  by - 15, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Mõm
  ctx.strokeStyle = '#e11d48';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-4, by - 5); ctx.lineTo(-1, by - 4); ctx.lineTo(2, by - 5);
  ctx.stroke();

  // Tay
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.arc(-8, by + 4, 3, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(4,  by + 4, 3, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
